// Map any form payload to the Gnanova portal-intake format.
const SOURCE_TAGS = ['Instagram', 'YouTube', 'WhatsApp Broadcast', 'LinkedIn', 'Channel Partner Referral', 'Cold Database'];
const ALIASES = { ig: 'Instagram', insta: 'Instagram', yt: 'YouTube', whatsapp: 'WhatsApp Broadcast', wa: 'WhatsApp Broadcast', referral: 'Channel Partner Referral', cp: 'Channel Partner Referral' };

return $input.all().map(({ json }) => {
  const b = json.body ?? json;
  const pick = (...keys) => keys.map((k) => b[k]).find((v) => v != null && String(v).trim() !== '');
  const rawSource = String(pick('source', 'utm_source') ?? '').trim().toLowerCase();
  const source = SOURCE_TAGS.find((t) => t.toLowerCase() === rawSource) ?? ALIASES[rawSource] ?? '';

  return {
    json: {
      workspace: 'viseshta-avenues',
      name: String(pick('name', 'full_name', 'fullName') ?? 'Unknown').trim(),
      phone: String(pick('phone', 'mobile', 'phone_number', 'whatsapp') ?? '').trim(),
      email: pick('email') ?? null,
      city: pick('city', 'location') ?? null,
      source,
      campaign: String(pick('campaign', 'utm_campaign') ?? 'Manasa'),
      investment_budget: pick('investment_budget', 'budget') ?? null,
      occupation: pick('occupation') ?? null,
      units_interested: pick('units_interested', 'units') ?? null,
      notes: pick('notes', 'message') ?? null,
    },
  };
});
